// StreamControl controls a stream that runs in the background, returned by
// [SandboxInstanceProcessService.StreamLogs] and [SandboxInstanceFSService.Watch].
type StreamControl struct {
	// Close stops the stream. It does not stop the process or change any file.
	Close func()
	done  chan struct{}
	err   error // Written before done closes.
}

// Wait blocks until the streaming operation completes.
func (sc *StreamControl) Wait() {
	if sc.done != nil {
		<-sc.done
	}
}

// Err waits for the stream to finish and returns its error. A clean log-stream
// end does not imply that the remote process completed. Explicit Close is clean.
func (sc *StreamControl) Err() error {
	sc.Wait()
	return sc.err
}

var errStreamClosed = errors.New("stream explicitly closed")

