// ============================================================================
// Session Service
// ============================================================================

// SandboxInstanceSessionService manages the sessions of one sandbox:
// short-lived, token-protected URLs of the sandbox API that let a client
// without a Blaxel API key, such as a browser, use the sandbox. A session is
// a private preview named session-<unix milliseconds> plus a preview token.
// Reach it through the Sessions field of a [SandboxInstance], and open a
// session with [SandboxService.FromSession].
type SandboxInstanceSessionService struct {
	sandboxName string
	options     []option.RequestOption
	service     *SandboxPreviewService
}

// Create creates a session: a private preview of the sandbox API and a
// token for it, both expiring at opts.ExpiresAt (24 hours from now by
// default). opts may be nil.
func (r *SandboxInstanceSessionService) Create(ctx context.Context, opts *SessionCreateOptions) (*SessionWithToken, error) {
	if opts == nil {
		opts = &SessionCreateOptions{}
	}

	expiresAt := time.Now().Add(24 * time.Hour) // Default: 1 day from now
	if opts.ExpiresAt != nil {
		expiresAt = *opts.ExpiresAt
	}

	sessionName := fmt.Sprintf("session-%d", time.Now().UnixMilli())

	preview, err := r.service.New(ctx, r.sandboxName, SandboxPreviewNewParams{
		Preview: PreviewParam{
			Metadata: PreviewMetadataParam{
				Name: sessionName,
			},
			Spec: PreviewSpecParam{
				Port:            Int(443),
				Public:          Bool(false),
				Expires:         String(expiresAt.Format(time.RFC3339)),
				RequestHeaders:  opts.RequestHeaders,
				ResponseHeaders: opts.ResponseHeaders,
			},
		},
	}, r.options...)
	if err != nil {
		return nil, err
	}

	// Create a token for the preview
	tokenService := NewSandboxPreviewTokenService(r.options...)
	token, err := tokenService.New(ctx, sessionName, SandboxPreviewTokenNewParams{
		SandboxName: r.sandboxName,
		PreviewToken: PreviewTokenParam{
			Metadata: PreviewTokenMetadataParam{
				Name: fmt.Sprintf("token-%d", time.Now().UnixMilli()),
			},
			Spec: PreviewTokenSpecParam{
				ExpiresAt: String(expiresAt.Format(time.RFC3339)),
			},
		},
	}, r.options...)
	if err != nil {
		return nil, err
	}

	tokenExpiresAt, _ := time.Parse(time.RFC3339, token.Spec.ExpiresAt)

	return &SessionWithToken{
		Name:      sessionName,
		URL:       preview.Spec.URL,
		Token:     token.Spec.Token,
		ExpiresAt: tokenExpiresAt,
	}, nil
}

// CreateIfExpired returns the first session of this sandbox while it stays
// valid for at least delta (1 hour when 0). Otherwise it deletes that session
// and creates a new one with opts. It creates one when there is none.
func (r *SandboxInstanceSessionService) CreateIfExpired(ctx context.Context, opts *SessionCreateOptions, delta time.Duration) (*SessionWithToken, error) {
	if delta == 0 {
		delta = time.Hour // Default: 1 hour threshold
	}

	// List existing sessions
	sessions, err := r.List(ctx)
	if err != nil {
		return nil, err
	}

	now := time.Now()
	threshold := now.Add(delta)

	// If we have sessions, check if any are still valid
	if len(sessions) > 0 {
		session := sessions[0]
		if session.ExpiresAt.After(threshold) {
			return &session, nil
		}
		// Session is expired or about to expire, delete it
		_ = r.Delete(ctx, session.Name)
	}

	// Create a new session
	return r.Create(ctx, opts)
}

// List returns the sessions of this sandbox (its previews named
// session-...), each with its first token. Sessions without a token are left
// out.
func (r *SandboxInstanceSessionService) List(ctx context.Context) ([]SessionWithToken, error) {
	previews, err := r.service.List(ctx, r.sandboxName, r.options...)
	if err != nil {
		return nil, err
	}

	if previews == nil {
		return []SessionWithToken{}, nil
	}

	var sessions []SessionWithToken
	tokenService := NewSandboxPreviewTokenService(r.options...)

	for _, preview := range *previews {
		// Only include previews that are sessions (name starts with "session-")
		if !strings.HasPrefix(preview.Metadata.Name, "session-") {
			continue
		}

		// Get token for this preview
		tokens, err := tokenService.Get(ctx, preview.Metadata.Name, SandboxPreviewTokenGetParams{
			SandboxName: r.sandboxName,
		}, r.options...)
		if err != nil || tokens == nil || len(*tokens) == 0 {
			continue
		}

		token := (*tokens)[0]
		expiresAt, _ := time.Parse(time.RFC3339, token.Spec.ExpiresAt)

		sessions = append(sessions, SessionWithToken{
			Name:      preview.Metadata.Name,
			URL:       preview.Spec.URL,
			Token:     token.Spec.Token,
			ExpiresAt: expiresAt,
		})
	}

	return sessions, nil
}

// Get returns a session by name with its URL, first token and expiry.
func (r *SandboxInstanceSessionService) Get(ctx context.Context, name string) (*SessionWithToken, error) {
	preview, err := r.service.Get(ctx, name, SandboxPreviewGetParams{
		SandboxName: r.sandboxName,
	}, r.options...)
	if err != nil {
		return nil, err
	}

	// Get token for this preview
	tokenService := NewSandboxPreviewTokenService(r.options...)
	tokens, err := tokenService.Get(ctx, name, SandboxPreviewTokenGetParams{
		SandboxName: r.sandboxName,
	}, r.options...)
	if err != nil {
		return nil, err
	}

	var tokenValue string
	var expiresAt time.Time
	if tokens != nil && len(*tokens) > 0 {
		token := (*tokens)[0]
		tokenValue = token.Spec.Token
		expiresAt, _ = time.Parse(time.RFC3339, token.Spec.ExpiresAt)
	}

	return &SessionWithToken{
		Name:      name,
		URL:       preview.Spec.URL,
		Token:     tokenValue,
		ExpiresAt: expiresAt,
	}, nil
}

// Delete deletes a session by name. Its URL and token stop working.
func (r *SandboxInstanceSessionService) Delete(ctx context.Context, name string) error {
	_, err := r.service.Delete(ctx, name, SandboxPreviewDeleteParams{
		SandboxName: r.sandboxName,
	}, r.options...)
	return err
}

// ============================================================================
// System Service
// ============================================================================

// SandboxInstanceSystemService maintains the sandbox API server that runs in
// one sandbox. Reach it through the System field of a [SandboxInstance].
type SandboxInstanceSystemService struct {
	sandboxName string
	options     []option.RequestOption
	service     *SandboxSystemService
}

// Upgrade triggers an upgrade of the sandbox-api process.
// Returns immediately before upgrading. The upgrade will: download the specified
// binary from GitHub releases, validate it, and restart.
// All running processes will be preserved across the upgrade.
func (r *SandboxInstanceSystemService) Upgrade(ctx context.Context, body SandboxSystemUpgradeParams, opts ...option.RequestOption) (*UpgradeTriggerResponse, error) {
	return r.service.Upgrade(ctx, body, opts...)
}

// Health returns health status and system information including upgrade count and binary details.
// Also includes last upgrade attempt status with detailed error information if available.
func (r *SandboxInstanceSystemService) Health(ctx context.Context, opts ...option.RequestOption) (*HealthResponse, error) {
	return r.service.Health(ctx, opts...)
}

// UpgradeAndWait triggers an upgrade and waits for it to complete by polling the
// health endpoint. If the upgrade fails transiently, it automatically retries up
// to maxRetries times. maxWait is the total wall-clock time to wait for the
// upgrade to succeed (including retries). Pass 0 for defaults (60s, 3 retries).
func (r *SandboxInstanceSystemService) UpgradeAndWait(ctx context.Context, body SandboxSystemUpgradeParams, maxWait time.Duration, maxRetries int, opts ...option.RequestOption) (*HealthResponse, error) {
	if maxWait == 0 {
		maxWait = 60 * time.Second
	}
	if maxRetries == 0 {
		maxRetries = 3
	}
	pollInterval := 500 * time.Millisecond
	retries := 0

	// Trigger the initial upgrade
	_, err := r.Upgrade(ctx, body, opts...)
	if err != nil {
		return nil, fmt.Errorf("failed to trigger upgrade: %w", err)
	}

	deadline := time.Now().Add(maxWait)
	var lastHealth *HealthResponse

	for {
		if time.Now().After(deadline) {
			return nil, fmt.Errorf("upgrade did not complete within %v, last health: %+v", maxWait, lastHealth)
		}

		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(pollInterval):
		}

		health, err := r.Health(ctx, opts...)
		if err != nil {
			continue
		}
		lastHealth = health

		if health.UpgradeCount > 0 {
			return health, nil
		}

		if health.LastUpgrade.Status == "failed" {
			if retries >= maxRetries {
				return nil, fmt.Errorf("upgrade failed after %d retries: %s", retries, health.LastUpgrade.Error)
			}
			retries++
			_, err = r.Upgrade(ctx, body, opts...)
			if err != nil {
				return nil, fmt.Errorf("failed to re-trigger upgrade (retry %d): %w", retries, err)
			}
		}
	}
}

// ============================================================================
// Constructors
// ============================================================================

// newSandboxInstance creates a SandboxInstance from a Sandbox response
func newSandboxInstance(sandbox *Sandbox, sandboxService *SandboxService, opts []option.RequestOption) *SandboxInstance {
	sandboxName := sandbox.Metadata.Name

	// Use the sandbox's URL as the base URL for sandbox-specific services
	// The sandbox URL must be appended LAST so it takes precedence over any
	// base URL that may already be in opts (from the parent client)
	sandboxOpts := opts
	if sandbox.Metadata.URL != "" {
		sandboxOpts = append(opts, option.WithBaseURL(sandbox.Metadata.URL))
	}

	processService := NewSandboxProcessService(sandboxOpts...)
	fsService := NewSandboxFilesystemService(sandboxOpts...)
	codegenService := NewSandboxCodegenService(sandboxOpts...)
	previewService := NewSandboxPreviewService(opts...)
	systemService := NewSandboxSystemService(sandboxOpts...)

	return &SandboxInstance{
		Sandbox: sandbox,
		Process: &SandboxInstanceProcessService{
			sandboxName: sandboxName,
			options:     sandboxOpts,
			service:     &processService,
		},
		FS: &SandboxInstanceFSService{
			sandboxName: sandboxName,
			options:     sandboxOpts,
			service:     &fsService,
		},
		Codegen: &SandboxInstanceCodegenService{
			sandboxName: sandboxName,
			options:     sandboxOpts,
			service:     &codegenService,
		},
		Previews: &SandboxInstancePreviewService{
			sandboxName: sandboxName,
			options:     opts,
			service:     &previewService,
		},
		Sessions: &SandboxInstanceSessionService{
			sandboxName: sandboxName,
			options:     opts,
			service:     &previewService,
		},
		System: &SandboxInstanceSystemService{
			sandboxName: sandboxName,
			options:     sandboxOpts,
			service:     &systemService,
		},
		sandboxService: sandboxService,
		options:        sandboxOpts,
	}
}

// newPreviewInstance creates a PreviewInstance from a Preview response
func newPreviewInstance(preview *Preview, sandboxName string, opts []option.RequestOption) *PreviewInstance {
	previewName := preview.Metadata.Name
	tokenService := NewSandboxPreviewTokenService(opts...)

	return &PreviewInstance{
		Preview: preview,
		Tokens: &PreviewInstanceTokenService{
			sandboxName: sandboxName,
			previewName: previewName,
			options:     opts,
			service:     &tokenService,
		},
	}
}
